// BashSharpParserInit initializes any static state used to implement BashSharpParser. By default the
// static state used to implement the parser is lazily initialized during the first call to
// NewBashSharpParser(). You can call this function if you wish to initialize the static state ahead
// of time.
func BashSharpParserInit() {
	staticData := &BashSharpParserParserStaticData
	staticData.once.Do(bashsharpparserParserInit)
}

// NewBashSharpParser produces a new parser instance for the optional input antlr.TokenStream.
func NewBashSharpParser(input antlr.TokenStream) *BashSharpParser {
	BashSharpParserInit()
	this := new(BashSharpParser)
	this.BaseParser = antlr.NewBaseParser(input)
	staticData := &BashSharpParserParserStaticData
	this.Interpreter = antlr.NewParserATNSimulator(this, staticData.atn, staticData.decisionToDFA, staticData.PredictionContextCache)
	this.RuleNames = staticData.RuleNames
	this.LiteralNames = staticData.LiteralNames
	this.SymbolicNames = staticData.SymbolicNames
	this.GrammarFileName = "BashSharpParser.g4"

	return this
}

// Note that '@members' cannot be changed now, but this should have been 'globals'
// If you are looking to have variables for each instance, use '@structmembers'

func compositeLitOK(ctx antlr.ParserRuleContext) bool {
	for ctx != nil {
		switch c := ctx.(type) {
		case *BlockContext, *ArgumentsContext, *IndexContext, *Slice_Context, *TypeArgsContext,
			*ArrayLengthContext, *LiteralValueContext, *ConversionContext,
			*ExprCaseClauseContext, *TypeCaseClauseContext, *CommClauseContext:
			return true
		case *OperandContext:
			if c.L_PAREN() != nil {
				return true
			}
		case *IfStmtContext, *ExprSwitchStmtContext, *TypeSwitchStmtContext, *ForStmtContext:
			return false
		}
		parent, ok := ctx.GetParent().(antlr.ParserRuleContext)
		if !ok {
			return true
		}
		ctx = parent
	}
	return true
}

